+void ChassisDriverNode::EvaluateLinkLiveness() {
+  // 上行帧超时判定：串口句柄仍在但 MCU 停发，属于"假活"。
+  // 必须在每一次轮询都执行——包括 Read() 返回空的那条路径——
+  // 否则 PTY 拔线（master 关闭后 read 返回 0）永远不会被识别。
+  if (!has_odom_packet_) {
