+void ChassisDriverNode::PublishBatteryState(
+    const amr_dispatcher_core::chassis::ChassisOdometryPacket& o, const rclcpp::Time& stamp) {
+  if (!o.battery_voltage.has_value() || *o.battery_voltage <= 0.0) {
