106	long long SafeScanInt(const std::string& text, std::size_t from) {
107	  std::size_t i = from;
108	  while (i < text.size() && std::isspace(static_cast<unsigned char>(text[i]))) ++i;
109	  bool negative = false;
110	  if (i < text.size() && (text[i] == '-' || text[i] == '+')) {
111	    negative = (text[i] == '-');
112	    ++i;
113	  }
114	  long long value = 0;
115	  bool any = false;
116	  while (i < text.size() && text[i] >= '0' && text[i] <= '9') {
117	    value = value * 10 + (text[i] - '0');
118	    if (value > 1000000000LL) {  // 地图尺寸/整数参数远小于此，超了按 0 处理
119	      return 0;
120	    }
121	    any = true;
122	    ++i;
123	  }
124	  if (!any) return 0;
125	  return negative ? -value : value;
126	}
