128	// 同理读一个浮点数：只接受 [-,+]digits[.digits][eE[+,-]digits] 的前缀。
129	double SafeScanDouble(const std::string& text, std::size_t from) {
130	  std::size_t i = from;
131	  while (i < text.size() && std::isspace(static_cast<unsigned char>(text[i]))) ++i;
132	  const std::size_t begin = i;
133	  if (i < text.size() && (text[i] == '-' || text[i] == '+')) ++i;
134	  bool digits = false;
135	  while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) {
136	    ++i;
137	    digits = true;
138	  }
139	  if (i < text.size() && text[i] == '.') {
140	    ++i;
141	    while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) {
142	      ++i;
143	      digits = true;
144	    }
145	  }
146	  if (!digits) return 0.0;
147	  if (i < text.size() && (text[i] == 'e' || text[i] == 'E')) {
148	    std::size_t j = i + 1;
149	    if (j < text.size() && (text[j] == '+' || text[j] == '-')) ++j;
150	    bool exp_digits = false;
151	    while (j < text.size() && std::isdigit(static_cast<unsigned char>(text[j]))) {
152	      ++j;
153	      exp_digits = true;
154	    }
155	    if (exp_digits) i = j;
156	  }
157	  const std::string num = text.substr(begin, i - begin);
158	  try {
159	    return std::stod(num);
160	  } catch (...) {
161	    // num 已由上面的正则式扫描保证形状合法，这里只是防御
162	    return 0.0;
163	  }
164	}
165	
166	// 完整写出一段字节；对端提前关闭时返回 false（不抛、不崩）。
167	bool WriteAll(int fd, const std::string& data) {
168	  std::size_t sent = 0;
169	  while (sent < data.size()) {
170	    const ssize_t n = ::send(fd, data.data() + sent, data.size() - sent, MSG_NOSIGNAL);
171	    if (n > 0) {
172	      sent += static_cast<std::size_t>(n);
173	      continue;
174	    }
175	    if (n < 0 && errno == EINTR) continue;
176	    return false;  // EPIPE / EAGAIN（已超时）/ 其它
177	  }
178	  return true;
179	}
180	
181	// 错误响应后先把对端还在发送的数据读掉再关闭。
182	// 直接 close 一个仍有未读数据的连接会发 RST，客户端可能连 400/413 都收不到。
183	// 上限 2 MiB + 单次读超时，恶意客户端最多多占一个读超时。
184	void DrainForClose(int fd, std::size_t max_bytes = 2U * 1024U * 1024U) {
185	  char sink[4096];
186	  std::size_t drained = 0;
187	  while (drained < max_bytes) {
188	    const ssize_t n = ::read(fd, sink, sizeof(sink));
189	    if (n > 0) {
190	      drained += static_cast<std::size_t>(n);
191	      continue;
192	    }
193	    if (n < 0 && errno == EINTR) continue;
194	    return;
195	  }
196	}
