226	void SafetyGateNode::WatchdogHeartbeatCallback(const std_msgs::msg::Bool::SharedPtr /*msg*/,
227	                                               const std::string& source) {
228	  // I1：心跳到达即打点（真实数据到达点，而非巡检周期）
229	  last_data_arrival_["watchdog"] = std::chrono::steady_clock::now();
230	  // B1 分源喂狗：只 Feed 回调登记的来源，watched_nodes_ 里每个源独立计时。
231	  if (watchdog_) {
232	    watchdog_->FeedHeartbeat(source);
233	  }
234	}
235	
236	void SafetyGateNode::WatchdogTick() {
237	  if (!watchdog_ || !gate_ || !fault_supervisor_) return;
238	
239	  auto events = watchdog_->Inspect(watched_nodes_);
240	  watchdog_ok_ = events.empty();
241	  for (auto& ev : events) {
